    brand_ticketsolve: { path: 'M68.09188,101.159h-.00049V63.22437L97.99082,33.39865a1,1,0,0,0-.70623-1.708H68.09139V1a1,1,0,0,0-1-1H31.15627a1,1,0,0,0-1,1V31.72943L.29577,61.51639a1,1,0,0,0,.70624,1.708H30.15627v37.46624a1,1,0,0,0,.35983.76823l36.22743,31.37344a1,1,0,0,0,1.34728-.06113l29.9051-29.905a1,1,0,0,0-.7071-1.7071H68.09188Z', fill: 'currentColor', stroke: 'none', viewbox: '-17.4 0 133.06 133.06' }
  }.freeze

  SIZE_CLASSES = {
    '3' => 'size-3',
    '4' => 'size-4',
    '5' => 'size-5',
    '6' => 'size-6',
    '8' => 'size-8',
    '10' => 'size-10',
    '12' => 'size-12',
    '16' => 'size-16'
  }.freeze

  # rubocop:disable Metrics/PerceivedComplexity
  # rubocop:disable Metrics/CyclomaticComplexity

  # Render an SVG icon
  # @param name [Symbol] Icon name from ICONS hash
  # @param size [String|nil] Tailwind size class (e.g., "4", "5", "8")
  # @param css_class [String] Additional CSS classes
  # @return [String] HTML-safe SVG element
  # Size mapping to Tailwind classes (size-N for better JIT detection)
  # Helpful Tailwind classes: `text-{colour}`, `stroke-{i}`, `stroke-[{f}]`
  def svg_icon(name, size: '5', css_class: '', data: {})
    entry = ICONS[name.to_sym]
    return content_tag(:span, "[icon:#{name}]", class: 'text-error') unless entry

    # these can be overridden by using a Hash instead of String value in ICONS. css_class can be extended in the same way
    fill = 'none'
    stroke = 'currentColor'
    stroke_linecap = 'round'
    stroke_linejoin = 'round'
    stroke_width = '2'
    viewbox = '0 0 24 24'

    if entry.is_a? Hash
      # required
      path = entry[:path]
      # optional
      css_class += " #{entry[:css_class]}" if entry[:css_class].present?
      fill = entry[:fill] if entry[:fill].present?
      stroke = entry[:stroke] if entry[:stroke].present?
      stroke_linecap = entry[:stroke_linecap] if entry[:stroke_linecap].present?
      stroke_linejoin = entry[:stroke_linejoin] if entry[:stroke_linejoin].present?
      stroke_width = entry[:stroke_width] if entry[:stroke_width].present?
      viewbox = entry[:viewbox] if entry[:viewbox].present?
    else
      path = entry
    end

    size_class = SIZE_CLASSES[size.to_s] || ''
    # output no size_class or style if size<=0,
    style = if size&.to_i&.positive? && size_class.blank?
              "width: #{0.25 * size.to_f}rem; height: #{0.25 * size.to_f}rem;"
            else
              ''
            end
    # A flex row whose text truncates or wraps would otherwise squash the icon.
    classes = [size_class, 'shrink-0', *css_class.to_s.split].compact_blank.uniq.join(' ')

    tag.svg(
      class: classes,
      data: { icon_name: name.to_s, **data },
      # Icons sit beside text or inside a named control, so screen readers skip them
      aria: { hidden: true },
      fill:,
      stroke:,
      'stroke-linecap': stroke_linecap,
      'stroke-linejoin': stroke_linejoin,
      'stroke-width': stroke_width,
      style:,
      viewBox: viewbox
    ) do
      tag.path(d: path)
    end
  end
  # rubocop:enable Metrics/PerceivedComplexity
  # rubocop:enable Metrics/CyclomaticComplexity

  # Shorthand method
  def icon(name, **)
    svg_icon(name, **)
  end
end
